import java.util.*;import com.koios.game.arpg.*;import com.koios.game.model.*;import com.koios.game.model.item.*;import com.koios.game.model.player.Player;import com.koios.GameService;import com.koios.network.GamePacket;import com.koios.client.stream.Stream;
public final class GroundLootMetadataCheck {
 static int checks;static void check(boolean b,String label){checks++;if(!b)throw new AssertionError(label);}
 static List<String> events(Player p,int from){List<GamePacket> packets=((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets;List<String> out=new ArrayList<>();for(int i=from;i<packets.size();i++){GamePacket packet=packets.get(i);if(packet.getOpcode()!=126)continue;byte[] bytes=new byte[packet.getSize()];packet.getBuffer().getBytes(packet.getBuffer().readerIndex(),bytes);Stream s=new Stream(bytes);String value=s.readString();if(s.method435()==65522)out.add(value);}return out;}
 static int mark(Player p){return ((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets.size();}
 static Map<String,String[]> state(Player p,int from){Map<String,String[]> map=new LinkedHashMap<>();for(String e:events(p,from)){String[] f=e.split("\\|",-1);if(f[0].equals("clear"))map.clear();else if(f[0].equals("remove"))map.remove(f[1]);else if(f[0].equals("add"))map.put(f[1],f);}return map;}
 public static void main(String[]args)throws Exception{PrototypeIntegrationCheck.loaded();Player p=PrototypeIntegrationCheck.player("lootowner",70),other=PrototypeIntegrationCheck.player("lootother",71);p.setAttribute("starter-claimed",true);p.setAttribute("intro-complete",true);p.setAttribute("tutorial-stage",11);MapRuns.home(p);PrototypeIntegrationCheck.idle(p);Location at=p.getLocation().copy();int from=mark(p),foreignFrom=mark(other);Item a=MapRuns.gem(1,false),b=MapRuns.gem(1,false);GroundItemManager.spawnPrivate(p,a,at);GroundItemManager.spawnPrivate(p,b,at);Map<String,String[]> labels=state(p,from);check(labels.size()==2,"Same base/tile rolled drops retain two distinct labels");Set<String> uuids=new HashSet<>();for(String[] f:labels.values()){check(f.length==10&&Integer.parseInt(f[2])==at.getX()&&Integer.parseInt(f[3])==at.getY()&&Integer.parseInt(f[4])==0,"Metadata has exact coordinates and agreed ten fields");uuids.add(f[6]);check(new String(Base64.getDecoder().decode(f[9]),java.nio.charset.StandardCharsets.UTF_8).contains("Level 1"),"Gem level readable in encoded name");}check(uuids.contains(a.getRoll().getInstanceId())&&uuids.contains(b.getRoll().getInstanceId()),"Labels carry actual per-item UUIDs");check(events(other,foreignFrom).isEmpty(),"Spawn never sends metadata to another owner");
  GroundItemManager.spawnPrivate(other,MapRuns.gem(2,true),at);int reload=mark(p);GameService.getGroundItemManager().reloadItems(p);check(state(p,reload).size()==2,"Reload never imports foreign-owner ground metadata");String firstKey=labels.keySet().iterator().next();check(GameService.getGroundItemManager().removeGroundItem(p,a.getId(),at.getX(),at.getY(),0,true),"Legacy pickup succeeds unchanged");check(p.getInventory().get(0).getRoll().getInstanceId().equals(a.getRoll().getInstanceId()),"Legacy pickup retains exact first ground UUID");check(events(p,from).contains("remove|"+firstKey)&&state(p,from).size()==1,"Pickup removes only matching entity label");
  for(int slot=0;slot<28;slot++)p.getInventory().set(slot,new Item(385));int failed=mark(p);check(!GameService.getGroundItemManager().removeGroundItem(p,b.getId(),at.getX(),at.getY(),0,true),"Full inventory pickup rejected");check(events(p,failed).isEmpty(),"Failed pickup keeps its label");p.getInventory().set(0,null);
  Location high=new Location(at.getX(),at.getY(),1);GroundItemManager.spawnPrivate(p,MapRuns.gem(3,false),high);int plane=mark(p);GroundItemManager.syncMetadata(p);check(state(p,plane).size()==1,"Snapshot excludes other plane");
  GroundItemManager.spawnPrivate(p,new Item(CraftingCurrency.IDS[0],3),at);GroundItemManager.spawnPrivate(p,new Item(MapRuns.PORTAL_SCROLL,5),at);GroundItemManager.spawnPrivate(p,new Item(995,30),at);GroundItemManager.spawnPrivate(p,new Item(385),at);int curr=mark(p);GroundItemManager.syncMetadata(p);check(state(p,curr).size()==4,"Currency/scrolls/coins labeled; unrelated legacy food omitted");
  MapRuns.home(p);PrototypeIntegrationCheck.idle(p);p.getInventory().set(0,MapRuns.map(1,0,1));MapRuns.start(p,0,false);PrototypeIntegrationCheck.idle(p);Location mapAt=p.getLocation().copy();Item mapGem=MapRuns.gem(2,true);GroundItemManager.spawnPrivate(p,mapGem,mapAt);int away=mark(p);GroundItemManager.syncMetadata(p);check(state(p,away).size()==1,"Map snapshot excludes old base labels");MapRuns.home(p);PrototypeIntegrationCheck.idle(p);int home=mark(p);GroundItemManager.syncMetadata(p);check(state(p,home).size()==4,"Returning home restores only base labels");MapRuns.enter(p);PrototypeIntegrationCheck.idle(p);int entry=mark(p);MapRuns.sendRegion(p);List<String> re=events(p,entry);check(re.get(0).equals("clear")&&state(p,entry).size()==1,"Post-profile region resend restores active map loot");
  MapRuns.cleanup(p);check(events(p,entry).stream().anyMatch(e->e.startsWith("remove|")),"Area cleanup removes remaining metadata records");GroundItemManager.clearArea(at.getX()-1,at.getY()-1,3);
  p.setPosition(3094,3493,0);PrototypeIntegrationCheck.idle(p);int expiry=mark(p);GroundItemManager.spawnNew(p,MapRuns.gem(1,false));for(int tick=0;tick<200;tick++)GroundItemManager.update();check(state(p,expiry).isEmpty()&&events(p,expiry).stream().anyMatch(e->e.startsWith("remove|")),"Legacy expiry removes owner label after visibility transition");System.out.println("Passed "+checks+" ground metadata identity/privacy/lifecycle checks.");}
}
